1-task-3","title":"Explain new launches versus existing running resources.","description":"Explain new launches versus existing running resources.","hint":"First identify the resource, time scope, and observable evidence that would distinguish the possible causes.","hints":["First identify the resource, time scope, and observable evidence that would distinguish the possible causes.","Use the request dataset capability introduced for this lesson to inspect or change the training state.","For this task, start with: request dataset — explain new launches versus existing running resources.."],"feedback":"Existing workloads are not assumed to update from registry push alone.","expectedOutcome":"Existing workloads are not assumed to update from registry push alone."}]'::jsonb, '["Changing a registry tag does not change existing running tasks."]'::jsonb, '{"files":{"/":{"type":"dir"},"/bin":{"type":"dir"},"/etc":{"type":"dir"},"/mnt":{"type":"dir"},"/opt":{"type":"dir"},"/tmp":{"type":"dir"},"/usr":{"type":"dir"},"/var":{"type":"dir"},"/home":{"type":"dir"},"/root":{"type":"dir"},"/media":{"type":"dir"},"/etc/apt":{"type":"dir"},"/usr/bin":{"type":"dir"},"/var/log":{"type":"dir"},"/tmp/.keep":{"type":"file","content":""},"/usr/local":{"type":"dir"},"/usr/share":{"type":"dir"},"/etc/hostname":{"type":"file","content":"learnbox"},"/etc/training":{"type":"dir"},"/home/learner":{"type":"dir"},"/usr/local/bin":{"type":"dir"},"/etc/os-release":{"type":"file","content":"PRETTY_NAME=\"Ubuntu 24.04.2 LTS\"\nNAME=\"Ubuntu\"\nVERSION_ID=\"24.04\"\nID=ubuntu\nID_LIKE=debian"},"/var/log/syslog":{"type":"file","content":"Training system initialized. All information in this simulator is fictional."},"/var/log/training":{"type":"dir"},"/home/learner/.bashrc":{"type":"file","content":"# ~/.bashrc: shell settings for learner@learnbox\nexport PS1=\"\\u@\\h:\\w$ \""},"/etc/training/app.json":{"type":"file","content":"{\n  \"name\": \"training-app\",\n  \"environment\": \"sandbox\",\n  \"port\